tool_schemas.implementation:
def weather(api_key, q=None, latitude=None, longitude=None, country_code=None, units=None, force_refresh=None, include_raw=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0226000" if __import__("os").path.isdir("./environment_mix/0226000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if not ss:
            return None
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None

    def _b62(n):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
        if n <= 0:
            return "0"
        out = []
        while n:
            n, r = divmod(n, 62)
            out.append(alphabet[r])
        return "".join(reversed(out))

    def _new_id(prefix):
        ms = int(time.time() * 1000)
        jitter = int(time.time_ns() % 1000000)
        return f"{prefix}_01H{_b62(ms)}{_b62(jitter)}"

    def _coerce_bool(x, default=False):
        if x is None:
            return default
        if isinstance(x, bool):
            return x
        return None  # invalid

    def _coerce_units(u):
        if u is None:
            return "metric"
        return u

    def _log_request(reqs, client_id, api_key_id, status_s, http_status_code,
                     location_id=None, snapshot_id=None, cache_status=None,
                     error_code=None, error_message=None,
                     upstream_latency_ms=None, total_latency_ms=0,
                     request_ip=None, request_user_agent=None):
        now_dt = _utcnow()
        row = {
            "id": _new_id("wthr_req"),
            "client_id": client_id,
            "api_key_id": api_key_id,
            "location_id": location_id,
            "snapshot_id": snapshot_id,
            "status": status_s,
            "cache_status": cache_status,
            "http_status_code": int(http_status_code),
            "error_code": error_code,
            "error_message": error_message,
            "upstream_latency_ms": upstream_latency_ms if upstream_latency_ms is None else int(upstream_latency_ms),
            "total_latency_ms": int(total_latency_ms) if isinstance(total_latency_ms, (int, float)) and total_latency_ms >= 0 else 0,
            "request_ip": request_ip,
            "request_user_agent": request_user_agent,
            "created_at": _iso(now_dt),
            "updated_at": _iso(now_dt),
        }
        reqs.append(row)
        return row

    t0 = time.time()

    # -------- Validate basic types/enums (do NOT over-reject; vendor schema is authoritative for types only) --------
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string.")

    # q in practice may be omitted; if provided but not string -> ignore if other lookup present; else error.
    if q is not None and not isinstance(q, str):
        if latitude is None or longitude is None:
            return _err("VALIDATION_ERROR", "q must be a string when provided (or omit q and use latitude/longitude).")
        q = None

    if country_code is not None:
        if not isinstance(country_code, str):
            return _err("VALIDATION_ERROR", "country_code must be a 2-letter ISO string when provided.")
        cc = country_code.strip().upper()
        if len(cc) != 2 or not cc.isalpha():
            return _err("VALIDATION_ERROR", "country_code must be a 2-letter ISO code (A-Z).")
        country_code = cc

    units = _coerce_units(units)
    if units not in ("metric", "imperial"):
        return _err("VALIDATION_ERROR", "units must be one of: metric, imperial.")

    force_refresh_b = _coerce_bool(force_refresh, default=False)
    if force_refresh_b is None:
        return _err("VALIDATION_ERROR", "force_refresh must be a boolean when provided.")
    include_raw_b = _coerce_bool(include_raw, default=False)
    if include_raw_b is None:
        return _err("VALIDATION_ERROR", "include_raw must be a boolean when provided.")

    # latitude/longitude validation if provided
    if latitude is not None and not isinstance(latitude, (int, float)):
        return _err("VALIDATION_ERROR", "latitude must be a number when provided.")
    if longitude is not None and not isinstance(longitude, (int, float)):
        return _err("VALIDATION_ERROR", "longitude must be a number when provided.")
    if latitude is not None and (latitude < -90 or latitude > 90):
        return _err("VALIDATION_ERROR", "latitude must be in [-90, 90].")
    if longitude is not None and (longitude < -180 or longitude > 180):
        return _err("VALIDATION_ERROR", "longitude must be in [-180, 180].")

    # -------- Authenticate (by id or key_prefix; never by key_hash) --------
    api_keys = _load("api_keys.json")
    api_clients = _load("api_clients.json")
    weather_requests = _load("weather_requests.json")
    locations = _load("locations.json")
    snapshots = _load("weather_snapshots.json")

    key_row = None
    for k in api_keys:
        if k.get("id") == api_key or k.get("key_prefix") == api_key:
            key_row = k
            break
    if not key_row:
        # cannot log without client_id; per contract return UNAUTHORIZED
        return _err("UNAUTHORIZED", "Invalid API key (no matching api_keys row by id or key_prefix).")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active.")

    client_row = next((c for c in api_clients if c.get("id") == key_row.get("client_id")), None)
    if not client_row:
        return _err("UNAUTHORIZED", "API key client_id does not reference an existing api_client.")
    client_id = client_row.get("id")
    api_key_id = key_row.get("id")

    # -------- Monthly reset reconciliation (counter-based) --------
    now = _utcnow()
    reset_at = _parse_dt(client_row.get("reset_at"))
    if reset_at is None:
        # Treat as validation/config error; log and reject.
        _log_request(
            weather_requests, client_id, api_key_id,
            "error", 500,
            error_code="invalid_request",
            error_message="Client reset_at is missing/invalid; cannot enforce quota.",
            total_latency_ms=int((time.time() - t0) * 1000),
        )
        _save("weather_requests.json", weather_requests)
        return _err("VALIDATION_ERROR", "Client reset_at is missing/invalid; cannot enforce quota.")
    if now >= reset_at:
        # Move to start of next month 00:00Z
        y, m = now.year, now.month
        if m == 12:
            ny, nm = y + 1, 1
        else:
            ny, nm = y, m + 1
        next_reset = datetime.datetime(ny, nm, 1, 0, 0, 0, tzinfo=datetime.timezone.utc)
        client_row["requests_this_month"] = 0
        client_row["reset_at"] = _iso(next_reset)
        client_row["updated_at"] = _iso(now)
        _save("api_clients.json", api_clients)

    # -------- Client status gate (must log exactly one request row) --------
    if client_row.get("status") != "active":
        http_status = 403
        status_s = "error"
        # quota-policy suspension can be treated as rate_limited
        if client_row.get("status") == "suspended":
            status_s = "rate_limited"
            http_status = 429
        _log_request(
            weather_requests, client_id, api_key_id,
            status_s, http_status,
            error_code="invalid_request",
            error_message="Client is not active (business rule: api_clients.status must be 'active').",
            total_latency_ms=int((time.time() - t0) * 1000),
        )
        _save("weather_requests.json", weather_requests)
        return _err("UNAUTHORIZED", "Client is not active (status must be 'active' to use weather).")

    # -------- Quota enforcement (non-enterprise monthly) --------
    plan = client_row.get("plan")
    if plan != "enterprise":
        quota = client_row.get("monthly_request_quota")
        used = client_row.get("requests_this_month")
        if not isinstance(quota, int) or quota < 0 or not isinstance(used, int) or used < 0:
            _log_request(
                weather_requests, client_id, api_key_id,
                "error", 500,
                error_code="invalid_request",
                error_message="Client quota counters are invalid; cannot enforce quota.",
                total_latency_ms=int((time.time() - t0) * 1000),
            )
            _save("weather_requests.json", weather_requests)
            return _err("VALIDATION_ERROR", "Client quota counters are invalid; cannot enforce quota.")
        if used >= quota:
            _log_request(
                weather_requests, client_id, api_key_id,
                "rate_limited", 429,
                error_code="quota_exceeded",
                error_message="Monthly request quota exceeded (business rule: non-enterprise must not exceed monthly_request_quota).",
                total_latency_ms=int((time.time() - t0) * 1000),
            )
            _save("weather_requests.json", weather_requests)
            return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded; retry after reset.", reset_at=client_row.get("reset_at"))

    # -------- Resolve location --------
    location_row = None
    if q is not None and q.strip():
        qn = " ".join(q.strip().split()).lower()
        # heuristic: match by display_name and optional country_code
        candidates = []
        for loc in locations:
            dn = loc.get("display_name")
            if isinstance(dn, str) and dn.strip().lower() == qn:
                if country_code is None or (loc.get("country_code") or "").upper() == country_code:
                    candidates.append(loc)
        if candidates:
            location_row = candidates[0]
        else:
            # If not found, reject (no creation by q; no geocoder in offline store)
            req = _log_request(
                weather_requests, client_id, api_key_id,
                "error", 400,
                error_code="invalid_request",
                error_message="Location not found for q within configured locations (business rule: referenced location must exist).",
                total_latency_ms=int((time.time() - t0) * 1000),
            )
            _save("weather_requests.json", weather_requests)
            return _err("NOT_FOUND", "Location not found for q in datastore.", request_id=req.get("id"))
    else:
        if latitude is None or longitude is None:
            req = _log_request(
                weather_requests, client_id, api_key_id,
                "error", 400,
                error_code="invalid_request",
                error_message="Missing location query; provide q or latitude/longitude.",
                total_latency_ms=int((time.time() - t0) * 1000),
            )
            _save("weather_requests.json", weather_requests)
            return _err("VALIDATION_ERROR", "Missing location query; provide q or latitude/longitude.", request_id=req.get("id"))

        # lookup or create configured location with exact lat/lon
        for loc in locations:
            if (isinstance(loc.get("latitude"), (int, float)) and isinstance(loc.get("longitude"), (int, float))
                and float(loc.get("latitude")) == float(latitude) and float(loc.get("longitude")) == float(longitude)
                and loc.get("source") in ("configured", "default", "ip")):
                location_row = loc
                break
        if not location_row:
            # create new configured location (enforce range already validated)
            now_iso = _iso(now)
            new_loc = {
                "id": _new_id("wthr_loc"),
                "source": "configured",
                "display_name": f"{latitude:.4f},{longitude:.4f}",
                "country_code": country_code,
                "latitude": float(latitude),
                "longitude": float(longitude),
                "timezone": None,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            locations.append(new_loc)
            _save("locations.json", locations)
            location_row = new_loc

    location_id = location_row.get("id")

    # -------- Cache / snapshot selection --------
    provider = "openweather"
    usable_snapshot = None
    latest_snapshot = None
    latest_dt = None
    for s in snapshots:
        if s.get("location_id") == location_id and s.get("provider") == provider:
            fa = _parse_dt(s.get("fetched_at"))
            if fa is not None and (latest_dt is None or fa > latest_dt):
                latest_dt = fa
                latest_snapshot = s

    if latest_snapshot:
        if latest_snapshot.get("status") == "fresh":
            exp = _parse_dt(latest_snapshot.get("expires_at"))
            if exp is not None and exp > now:
                usable_snapshot = latest_snapshot

    cache_status = None
    served_snapshot = None
    upstream_latency_ms = None

    def _convert_units_from_c(snapshot_row, target_units):
        # Only adjust presentation fields; raw_payload untouched.
        out = dict(snapshot_row)
        if target_units == "imperial":
            tc = out.get("temperature_c")
            if isinstance(tc, (int, float)):
                out["temperature_f"] = tc * 9.0 / 5.0 + 32.0
            ws = out.get("wind_speed_mps")
            if isinstance(ws, (int, float)):
                out["wind_speed_mph"] = ws * 2.2369362920544
        return out

    if usable_snapshot and not force_refresh_b:
        served_snapshot = usable_snapshot
        cache_status = "hit"
    else:
        # Attempt refresh (offline simulation): we cannot call upstream; mark failed and fallback if possible.
        cache_status = "miss" if latest_snapshot is None else "stale_refresh"
        refresh_start = time.time()
        upstream_latency_ms = int((time.time() - refresh_start) * 1000)  # near-zero but present

        # Update/create failed snapshot row per business rule
        now_iso = _iso(now)
        exp_iso = _iso(now + datetime.timedelta(minutes=15))
        if latest_snapshot:
            current_status = latest_snapshot.get("status")
            # enforce lifecycle transition to 'failed' if not already
            allowed = {
                "fresh": ["stale", "failed"],
                "stale": ["fresh", "failed"],
                "failed": ["fresh"],
            }
            if current_status != "failed":
                if current_status not in allowed or "failed" not in allowed[current_status]:
                    # Log error; cannot mutate snapshot due to invalid transition
                    req = _log_request(
                        weather_requests, client_id, api_key_id,
                        "error", 500,
                        location_id=location_id,
                        snapshot_id=latest_snapshot.get("id"),
                        error_code="invalid_transition",
                        error_message="Illegal weather_snapshot status transition to 'failed' (business rule: lifecycle transitions must be followed).",
                        upstream_latency_ms=upstream_latency_ms,
                        total_latency_ms=int((time.time() - t0) * 1000),
                    )
                    _save("weather_requests.json", weather_requests)
                    return _err("INVALID_TRANSITION", "Illegal snapshot lifecycle transition.", request_id=req.get("id"))
            latest_snapshot["status"] = "failed"
            latest_snapshot["error_message"] = "Upstream weather provider unavailable in offline mode during refresh."
            latest_snapshot["updated_at"] = now_iso
            # keep fetched_at/expires_at as-is; but ensure expires_at >= fetched_at if we touch them (we won't)
            _save("weather_snapshots.json", snapshots)
        else:
            # create new failed snapshot
            new_snap = {
                "id": _new_id("wthr_wx"),
                "location_id": location_id,
                "provider": provider,
                "status": "failed",
                "observed_at": None,
                "fetched_at": now_iso,
                "expires_at": exp_iso,
                "temperature_c": None,
                "humidity_pct": None,
                "wind_speed_mps": None,
                "conditions": None,
                "raw_payload": {"error": "offline_mode", "provider": provider},
                "error_message": "Upstream weather provider unavailable in offline mode during refresh.",
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            snapshots.append(new_snap)
            _save("weather_snapshots.json", snapshots)
            latest_snapshot = new_snap

        # Fallback policy: if we have any prior snapshot (even stale/failed), serve latest non-failed if exists else error.
        fallback = None
        if latest_snapshot and latest_snapshot.get("status") != "failed":
            fallback = latest_snapshot
        else:
            # find most recent non-failed snapshot if any
            for s in snapshots:
                if s.get("location_id") == location_id and s.get("provider") == provider and s.get("status") in ("fresh", "stale"):
                    fa = _parse_dt(s.get("fetched_at"))
                    if fa is not None and (fallback is None or fa > _parse_dt(fallback.get("fetched_at"))):
                        fallback = s

        if fallback:
            served_snapshot = fallback
            # keep cache_status miss/stale_refresh as already set
        else:
            req = _log_request(
                weather_requests, client_id, api_key_id,
                "error", 503,
                location_id=location_id,
                snapshot_id=latest_snapshot.get("id") if latest_snapshot else None,
                error_code="upstream_unavailable",
                error_message="Upstream refresh failed and no acceptable cached snapshot exists.",
                upstream_latency_ms=upstream_latency_ms,
                total_latency_ms=int((time.time() - t0) * 1000),
            )
            _save("weather_requests.json", weather_requests)
            return _err("CONFLICT", "Unable to serve weather: refresh failed and no cached snapshot available.", request_id=req.get("id"))

    # -------- Served response: must log exactly one row, update counters/last_used_at --------
    if not served_snapshot or not location_id or not served_snapshot.get("id"):
        # should not happen; log an internal error
        req = _log_request(
            weather_requests, client_id, api_key_id,
            "error", 500,
            location_id=location_id,
            snapshot_id=served_snapshot.get("id") if isinstance(served_snapshot, dict) else None,
            error_code="invalid_request",
            error_message="Internal error: served response missing required references (location_id/snapshot_id).",
            total_latency_ms=int((time.time() - t0) * 1000),
        )
        _save("weather_requests.json", weather_requests)
        return _err("CONFLICT", "Internal error: missing served references.", request_id=req.get("id"))

    # increment quota counter for non-enterprise
    if client_row.get("plan") != "enterprise":
        client_row["requests_this_month"] = int(client_row.get("requests_this_month", 0)) + 1
        client_row["updated_at"] = _iso(now)
        _save("api_clients.json", api_clients)

    # update api_key last_used_at
    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    req = _log_request(
        weather_requests, client_id, api_key_id,
        "served", 200,
        location_id=location_id,
        snapshot_id=served_snapshot.get("id"),
        cache_status=cache_status,
        upstream_latency_ms=upstream_latency_ms,
        total_latency_ms=int((time.time() - t0) * 1000),
    )
    _save("weather_requests.json", weather_requests)

    snap_out = dict(served_snapshot)
    if not include_raw_b:
        snap_out.pop("raw_payload", None)

    # Units presentation: keep stored Celsius + add derived fields for imperial
    snap_out = _convert_units_from_c(snap_out, units)

    return {
        "request": {
            "id": req.get("id"),
            "status": req.get("status"),
            "cache_status": req.get("cache_status"),
            "http_status_code": req.get("http_status_code"),
            "created_at": req.get("created_at"),
        },
        "location": location_row,
        "snapshot": snap_out,
        "units": units,
    }

def me(api_key, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0226000" if __import__("os").path.isdir("./environment_mix/0226000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            if s.tzinfo is None:
                return s.replace(tzinfo=datetime.timezone.utc)
            return s
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None

    def _b62(n):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
        if n <= 0:
            return "0"
        out = []
        while n:
            n, r = divmod(n, 62)
            out.append(alphabet[r])
        return "".join(reversed(out))

    def _new_id(prefix):
        ms = int(time.time() * 1000)
        jitter = int(time.time_ns() % 1000000)
        return f"{prefix}_01H{_b62(ms)}{_b62(jitter)}"

    def _find_key_row(presented):
        if not isinstance(presented, str) or not presented.strip():
            return None
        keys = _load("api_keys.json")
        for k in keys:
            if k.get("id") == presented or k.get("key_prefix") == presented:
                return k
        return None

    def _resolve_auth(presented):
        k = _find_key_row(presented)
        if not k:
            return None, None
        clients = _load("api_clients.json")
        c = next((cc for cc in clients if cc.get("id") == k.get("client_id")), None)
        return c, k

    def _log_request(reqs, client_id, api_key_id, status_s, http_status_code,
                     error_code=None, error_message=None, total_latency_ms=0):
        now_dt = _utcnow()
        row = {
            "id": _new_id("wthr_req"),
            "client_id": client_id,
            "api_key_id": api_key_id,
            "location_id": None,
            "snapshot_id": None,
            "status": status_s,
            "cache_status": None,
            "http_status_code": int(http_status_code),
            "error_code": error_code,
            "error_message": error_message,
            "upstream_latency_ms": None,
            "total_latency_ms": int(max(0, total_latency_ms)),
            "request_ip": None,
            "request_user_agent": None,
            "created_at": _iso(now_dt),
            "updated_at": _iso(now_dt),
        }
        reqs.append(row)
        _save("weather_requests.json", reqs)
        return row

    t0 = time.time()
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("UNAUTHORIZED", "Missing API key.")

    client, keyrow = _resolve_auth(api_key)
    if keyrow is None:
        return _err("UNAUTHORIZED", "Invalid API key.")
    if client is None:
        return _err("UNAUTHORIZED", "API client not found for key.")
    reqs = _load("weather_requests.json")

    # key must be active for me()
    if keyrow.get("status") != "active":
        latency_ms = int((time.time() - t0) * 1000)
        _log_request(reqs, client.get("id"), keyrow.get("id"), "error", 401, "invalid_key", "API key is revoked.", latency_ms)
        return _err("UNAUTHORIZED", "API key is revoked.", http_status_code=401)

    # If client not active, refuse (but still log)
    if client.get("status") != "active":
        latency_ms = int((time.time() - t0) * 1000)
        _log_request(reqs, client.get("id"), keyrow.get("id"), "error", 403, "client_inactive", "API client is not active.", latency_ms)
        return _err("UNAUTHORIZED", "API client is not active.", http_status_code=403)

    now_dt = _utcnow()
    # roll window if needed
    clients_all = _load("api_clients.json")
    reset_at = _parse_dt(client.get("reset_at"))
    if reset_at is not None and reset_at <= now_dt:
        first_next_month = (now_dt.replace(day=1, hour=0, minute=0, second=0) + datetime.timedelta(days=32)).replace(day=1)
        client["reset_at"] = _iso(first_next_month)
        client["requests_this_month"] = 0
        client["updated_at"] = _iso(now_dt)
        for i, cc in enumerate(clients_all):
            if cc.get("id") == client.get("id"):
                clients_all[i] = client
                break
        _save("api_clients.json", clients_all)

    latency_ms = int((time.time() - t0) * 1000)
    _log_request(reqs, client.get("id"), keyrow.get("id"), "served", 200, None, None, latency_ms)

    return {
        "api_key": {
            "id": keyrow.get("id"),
            "key_prefix": keyrow.get("key_prefix"),
            "status": keyrow.get("status"),
            "client_id": keyrow.get("client_id"),
            "last_used_at": keyrow.get("last_used_at"),
            "created_at": keyrow.get("created_at"),
            "updated_at": keyrow.get("updated_at"),
            "scopes": ["weather:read", "admin:read", "admin:write"],
        },
        "api_client": {
            "id": client.get("id"),
            "name": client.get("name"),
            "status": client.get("status"),
            "plan": client.get("plan"),
            "monthly_request_quota": client.get("monthly_request_quota"),
            "requests_this_month": client.get("requests_this_month"),
            "reset_at": client.get("reset_at"),
            "created_at": client.get("created_at"),
            "updated_at": client.get("updated_at"),
        },
        "quota": {
            "plan": client.get("plan"),
            "monthly_request_quota": client.get("monthly_request_quota"),
            "requests_this_month": client.get("requests_this_month"),
            "reset_at": client.get("reset_at"),
        }
    }

def api_clients_list(api_key, status=None, plan=None, name_contains=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0226000" if __import__("os").path.isdir("./environment_mix/0226000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _b62(n):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
        if n <= 0:
            return "0"
        out = []
        while n:
            n, r = divmod(n, 62)
            out.append(alphabet[r])
        return "".join(reversed(out))

    def _new_id(prefix):
        ms = int(time.time() * 1000)
        jitter = int(time.time_ns() % 1000000)
        return f"{prefix}_01H{_b62(ms)}{_b62(jitter)}"

    def _find_key_row(presented):
        if not isinstance(presented, str) or not presented.strip():
            return None
        keys = _load("api_keys.json")
        for k in keys:
            if k.get("id") == presented or k.get("key_prefix") == presented:
                return k
        return None

    def _resolve_auth(presented):
        k = _find_key_row(presented)
        if not k or k.get("status") != "active":
            return None, None
        clients = _load("api_clients.json")
        c = next((cc for cc in clients if cc.get("id") == k.get("client_id")), None)
        if not c or c.get("status") != "active":
            return None, None
        return c, k

    def _log_request(reqs, client_id, api_key_id, status_s, http_status_code,
                     error_code=None, error_message=None, total_latency_ms=0):
        now_dt = _utcnow()
        row = {
            "id": _new_id("wthr_req"),
            "client_id": client_id,
            "api_key_id": api_key_id,
            "location_id": None,
            "snapshot_id": None,
            "status": status_s,
            "cache_status": None,
            "http_status_code": int(http_status_code),
            "error_code": error_code,
            "error_message": error_message,
            "upstream_latency_ms": None,
            "total_latency_ms": int(max(0, total_latency_ms)),
            "request_ip": None,
            "request_user_agent": None,
            "created_at": _iso(now_dt),
            "updated_at": _iso(now_dt),
        }
        reqs.append(row)
        _save("weather_requests.json", reqs)
        return row

    def _encode_cursor(last_row):
        payload = {"id": last_row.get("id"), "created_at": last_row.get("created_at")}
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _decode_cursor(cur):
        try:
            pad = "=" * (-len(cur) % 4)
            raw = base64.urlsafe_b64decode((cur + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict):
                return None
            if not isinstance(obj.get("id"), str) or not isinstance(obj.get("created_at"), str):
                return None
            return obj
        except Exception:
            return None

    t0 = time.time()

    # Validate filters
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("UNAUTHORIZED", "Missing API key.")
    if status is not None and status not in ("active", "suspended", "deleted"):
        return _err("VALIDATION_ERROR", "Invalid status filter.")
    if plan is not None and plan not in ("free", "pro", "enterprise"):
        return _err("VALIDATION_ERROR", "Invalid plan filter.")
    if name_contains is not None and (not isinstance(name_contains, str) or not name_contains.strip()):
        return _err("VALIDATION_ERROR", "name_contains must be a non-empty string when provided.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")

    authed_client, authed_key = _resolve_auth(api_key)
    if authed_client is None:
        return _err("UNAUTHORIZED", "Invalid or inactive API key.")

    reqs = _load("weather_requests.json")

    # Read + filter
    clients = _load("api_clients.json")
    rows = clients[:]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if plan is not None:
        rows = [r for r in rows if r.get("plan") == plan]
    if name_contains is not None:
        needle = name_contains.strip().lower()
        rows = [r for r in rows if needle in (r.get("name") or "").lower()]

    # Sort deterministic by created_at, id
    rows.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""))

    # Cursor pagination
    start_idx = 0
    if cursor is not None:
        cobj = _decode_cursor(cursor)
        if cobj is None:
            latency_ms = int((time.time() - t0) * 1000)
            _log_request(reqs, authed_client.get("id"), authed_key.get("id"), "error", 400, "invalid_request", "Invalid cursor.", latency_ms)
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        # find the first row strictly after the cursor marker
        for i, r in enumerate(rows):
            if (r.get("created_at") or "", r.get("id") or "") > (cobj["created_at"], cobj["id"]):
                start_idx = i
                break
        else:
            start_idx = len(rows)

    page = rows[start_idx:start_idx + limit]
    has_more = (start_idx + limit) < len(rows)
    next_cursor = _encode_cursor(page[-1]) if has_more and page else None

    latency_ms = int((time.time() - t0) * 1000)
    _log_request(reqs, authed_client.get("id"), authed_key.get("id"), "served", 200, None, None, latency_ms)

    return {"data": page, "total": len(rows), "limit": limit, "has_more": has_more, "next_cursor": next_cursor}

def api_clients_update(api_key, id, name=None, plan=None, monthly_request_quota=None, reset_at=None, status=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0226000" if __import__("os").path.isdir("./environment_mix/0226000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            if s.tzinfo is None:
                return s.replace(tzinfo=datetime.timezone.utc)
            return s
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None

    def _b62(n):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
        if n <= 0:
            return "0"
        out = []
        while n:
            n, r = divmod(n, 62)
            out.append(alphabet[r])
        return "".join(reversed(out))

    def _new_id(prefix):
        ms = int(time.time() * 1000)
        jitter = int(time.time_ns() % 1000000)
        return f"{prefix}_01H{_b62(ms)}{_b62(jitter)}"

    def _find_key_row(presented):
        if not isinstance(presented, str) or not presented.strip():
            return None
        keys = _load("api_keys.json")
        for k in keys:
            if k.get("id") == presented or k.get("key_prefix") == presented:
                return k
        return None

    def _resolve_auth(presented):
        k = _find_key_row(presented)
        if not k or k.get("status") != "active":
            return None, None
        clients = _load("api_clients.json")
        c = next((cc for cc in clients if cc.get("id") == k.get("client_id")), None)
        if not c or c.get("status") != "active":
            return None, None
        return c, k

    def _log_request(reqs, client_id, api_key_id, status_s, http_status_code,
                     error_code=None, error_message=None, total_latency_ms=0):
        now_dt = _utcnow()
        row = {
            "id": _new_id("wthr_req"),
            "client_id": client_id,
            "api_key_id": api_key_id,
            "location_id": None,
            "snapshot_id": None,
            "status": status_s,
            "cache_status": None,
            "http_status_code": int(http_status_code),
            "error_code": error_code,
            "error_message": error_message,
            "upstream_latency_ms": None,
            "total_latency_ms": int(max(0, total_latency_ms)),
            "request_ip": None,
            "request_user_agent": None,
            "created_at": _iso(now_dt),
            "updated_at": _iso(now_dt),
        }
        reqs.append(row)
        _save("weather_requests.json", reqs)
        return row

    t0 = time.time()

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("UNAUTHORIZED", "Missing API key.")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string.")
    if name is not None and (not isinstance(name, str) or not name.strip()):
        return _err("VALIDATION_ERROR", "name must be a non-empty string when provided.")
    if plan is not None and plan not in ("free", "pro", "enterprise"):
        return _err("VALIDATION_ERROR", "Invalid plan.")
    if monthly_request_quota is not None:
        if not isinstance(monthly_request_quota, int) or monthly_request_quota < 0:
            return _err("VALIDATION_ERROR", "monthly_request_quota must be an integer >= 0.")
    if reset_at is not None:
        if not isinstance(reset_at, str) or _parse_dt(reset_at) is None:
            return _err("VALIDATION_ERROR", "reset_at must be an RFC3339 datetime string.")
    if status is not None and status not in ("active", "suspended", "deleted"):
        return _err("VALIDATION_ERROR", "Invalid status.")

    authed_client, authed_key = _resolve_auth(api_key)
    if authed_client is None:
        return _err("UNAUTHORIZED", "Invalid or inactive API key.")

    reqs = _load("weather_requests.json")
    clients = _load("api_clients.json")
    target_idx = None
    for i, c in enumerate(clients):
        if c.get("id") == id:
            target_idx = i
            break
    if target_idx is None:
        latency_ms = int((time.time() - t0) * 1000)
        _log_request(reqs, authed_client.get("id"), authed_key.get("id"), "error", 404, "not_found", "API client not found.", latency_ms)
        return _err("NOT_FOUND", "API client not found.")

    target = clients[target_idx]

    # unique(name)
    if name is not None:
        for c in clients:
            if c.get("id") != target.get("id") and (c.get("name") or "") == name:
                latency_ms = int((time.time() - t0) * 1000)
                _log_request(reqs, authed_client.get("id"), authed_key.get("id"), "error", 409, "conflict", "Client name must be unique.", latency_ms)
                return _err("CONFLICT", "Client name must be unique.")

    # lifecycle transition validation
    transitions = {
        "active": {"suspended", "deleted"},
        "suspended": {"active", "deleted"},
        "deleted": set()
    }
    if status is not None and status != target.get("status"):
        cur = target.get("status")
        if status not in transitions.get(cur, set()):
            latency_ms = int((time.time() - t0) * 1000)
            _log_request(reqs, authed_client.get("id"), authed_key.get("id"), "error", 409, "invalid_transition", f"Illegal client status transition {cur} -> {status}.", latency_ms)
            return _err("INVALID_TRANSITION", f"Illegal client status transition {cur} -> {status}.")

    # apply mutations
    changed = False
    if name is not None and name != target.get("name"):
        target["name"] = name
        changed = True
    if plan is not None and plan != target.get("plan"):
        target["plan"] = plan
        changed = True
    if monthly_request_quota is not None and monthly_request_quota != target.get("monthly_request_quota"):
        target["monthly_request_quota"] = int(monthly_request_quota)
        changed = True
    if reset_at is not None and reset_at != target.get("reset_at"):
        target["reset_at"] = reset_at
        changed = True
    if status is not None and status != target.get("status"):
        target["status"] = status
        changed = True

    # constraint: requests_this_month <= monthly_request_quota OR plan == enterprise
    if target.get("plan") != "enterprise":
        try:
            used = int(target.get("requests_this_month") or 0)
            quota = int(target.get("monthly_request_quota") or 0)
        except Exception:
            used, quota = 0, 0
        if used > quota:
            latency_ms = int((time.time() - t0) * 1000)
            _log_request(reqs, authed_client.get("id"), authed_key.get("id"), "error", 400, "invalid_request", "requests_this_month exceeds monthly_request_quota for non-enterprise plan.", latency_ms)
            return _err("VALIDATION_ERROR", "requests_this_month exceeds monthly_request_quota for non-enterprise plan.")

    if not changed:
        # no success without effect
        latency_ms = int((time.time() - t0) * 1000)
        _log_request(reqs, authed_client.get("id"), authed_key.get("id"), "error", 404, "not_found", "No changes applied (fields identical).", latency_ms)
        return _err("NOT_FOUND", "No changes applied.")

    target["updated_at"] = _iso(_utcnow())
    clients[target_idx] = target
    _save("api_clients.json", clients)

    latency_ms = int((time.time() - t0) * 1000)
    _log_request(reqs, authed_client.get("id"), authed_key.get("id"), "served", 200, None, None, latency_ms)

    return {"data": target}

def api_keys_create(api_key, client_id, label=None, **_extra):
    import json, os, datetime, time, secrets, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0226000" if __import__("os").path.isdir("./environment_mix/0226000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _b62(n):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
        if n <= 0:
            return "0"
        out = []
        while n:
            n, r = divmod(n, 62)
            out.append(alphabet[r])
        return "".join(reversed(out))

    def _new_id(prefix):
        ms = int(time.time() * 1000)
        jitter = int(time.time_ns() % 1000000)
        # datastore ids are 01J...; generate similarly
        return f"{prefix}_01J{_b62(ms)}{_b62(jitter)}"

    def _find_key_row(presented):
        if not isinstance(presented, str) or not presented.strip():
            return None
        keys = _load("api_keys.json")
        for k in keys:
            if k.get("id") == presented or k.get("key_prefix") == presented:
                return k
        return None

    def _resolve_auth(presented):
        k = _find_key_row(presented)
        if not k or k.get("status") != "active":
            return None, None
        clients = _load("api_clients.json")
        c = next((cc for cc in clients if cc.get("id") == k.get("client_id")), None)
        if not c or c.get("status") != "active":
            return None, None
        return c, k

    def _log_request(reqs, client_id_, api_key_id_, status_s, http_status_code,
                     error_code=None, error_message=None, total_latency_ms=0):
        now_dt = _utcnow()
        row = {
            "id": f"wthr_req_{_new_id('01J')}".replace("wthr_req_01J01J", "wthr_req_01J"),
            "client_id": client_id_,
            "api_key_id": api_key_id_,
            "location_id": None,
            "snapshot_id": None,
            "status": status_s,
            "cache_status": None,
            "http_status_code": int(http_status_code),
            "error_code": error_code,
            "error_message": error_message,
            "upstream_latency_ms": None,
            "total_latency_ms": int(max(0, total_latency_ms)),
            "request_ip": None,
            "request_user_agent": None,
            "created_at": _iso(now_dt),
            "updated_at": _iso(now_dt),
        }
        reqs.append(row)
        _save("weather_requests.json", reqs)
        return row

    t0 = time.time()

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("UNAUTHORIZED", "Missing API key.")
    if not isinstance(client_id, str) or not client_id.strip():
        return _err("VALIDATION_ERROR", "client_id must be a non-empty string.")
    if label is not None:
        if not isinstance(label, str) or not label.strip() or len(label) > 80:
            return _err("VALIDATION_ERROR", "label must be a non-empty string up to 80 chars when provided.")

    authed_client, authed_key = _resolve_auth(api_key)
    if authed_client is None:
        return _err("UNAUTHORIZED", "Invalid or inactive API key.")

    reqs = _load("weather_requests.json")
    clients = _load("api_clients.json")
    owner = next((c for c in clients if c.get("id") == client_id), None)
    if owner is None:
        latency_ms = int((time.time() - t0) * 1000)
        _log_request(reqs, authed_client.get("id"), authed_key.get("id"), "error", 404, "not_found", "Owning client not found.", latency_ms)
        return _err("NOT_FOUND", "Owning client not found.")
    if owner.get("status") != "active":
        latency_ms = int((time.time() - t0) * 1000)
        _log_request(reqs, authed_client.get("id"), authed_key.get("id"), "error", 409, "conflict", "Cannot create key for non-active client.", latency_ms)
        return _err("CONFLICT", "Cannot create key for non-active client.")

    keys = _load("api_keys.json")

    # create plaintext secret only once
    plaintext = "wthr_live_" + secrets.token_urlsafe(24).replace("-", "").replace("_", "")
    key_prefix = plaintext[:8]

    # unique(key_prefix)
    if any((k.get("key_prefix") == key_prefix) for k in keys):
        # extremely unlikely; regenerate once
        plaintext = "wthr_live_" + secrets.token_urlsafe(28).replace("-", "").replace("_", "")
        key_prefix = plaintext[:8]
        if any((k.get("key_prefix") == key_prefix) for k in keys):
            latency_ms = int((time.time() - t0) * 1000)
            _log_request(reqs, authed_client.get("id"), authed_key.get("id"), "error", 409, "conflict", "Could not allocate unique key_prefix.", latency_ms)
            return _err("CONFLICT", "Could not allocate unique key_prefix.")

    now_iso = _iso(_utcnow())
    new_row = {
        "id": _new_id("wthr_key"),
        "client_id": client_id,
        "key_prefix": key_prefix,
        # store a hash for realism (but never used for auth comparisons)
        "key_hash": hashlib.sha256(plaintext.encode("utf-8")).hexdigest(),
        "status": "active",
        "last_used_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    keys.append(new_row)
    _save("api_keys.json", keys)

    latency_ms = int((time.time() - t0) * 1000)
    _log_request(reqs, authed_client.get("id"), authed_key.get("id"), "served", 201, None, None, latency_ms)

    return {
        "data": {
            "id": new_row["id"],
            "client_id": new_row["client_id"],
            "key_prefix": new_row["key_prefix"],
            "status": new_row["status"],
            "last_used_at": new_row["last_used_at"],
            "created_at": new_row["created_at"],
            "updated_at": new_row["updated_at"],
            "label": label
        },
        "plaintext_key": plaintext
    }

def api_keys_update(api_key, id, status, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0226000" if __import__("os").path.isdir("./environment_mix/0226000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _b62(n):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
        if n <= 0:
            return "0"
        out = []
        while n:
            n, r = divmod(n, 62)
            out.append(alphabet[r])
        return "".join(reversed(out))

    def _new_id(prefix):
        ms = int(time.time() * 1000)
        jitter = int(time.time_ns() % 1000000)
        return f"{prefix}_01H{_b62(ms)}{_b62(jitter)}"

    def _coerce_rows(obj):
        # Accept either [{".."}] or {"rows":[{".."}]}
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"]
        if isinstance(obj, list):
            return obj
        return []

    def _write_collection(filename, rows):
        # Preserve on-disk envelope shape (list vs {"rows": [...]})
        existing = _load(filename)
        if isinstance(existing, dict) and isinstance(existing.get("rows"), list):
            existing["rows"] = rows
            _save(filename, existing)
        else:
            _save(filename, rows)

    def _append_request_log(req_row):
        wr = _load("weather_requests.json")
        if isinstance(wr, dict) and isinstance(wr.get("rows"), list):
            wr["rows"].append(req_row)
            _save("weather_requests.json", wr)
        elif isinstance(wr, list):
            wr.append(req_row)
            _save("weather_requests.json", wr)
        else:
            _save("weather_requests.json", {"rows": [req_row]})

    def _log_request(client_id, api_key_id, status_s, http_status_code,
                     error_code=None, error_message=None, total_latency_ms=0):
        now_dt = _utcnow()
        row = {
            "id": _new_id("wthr_req"),
            "client_id": client_id,
            "api_key_id": api_key_id,
            "location_id": None,
            "snapshot_id": None,
            "status": status_s,
            "cache_status": None,
            "http_status_code": int(http_status_code),
            "error_code": error_code,
            "error_message": error_message,
            "upstream_latency_ms": None,
            "total_latency_ms": int(total_latency_ms) if isinstance(total_latency_ms, (int, float)) and total_latency_ms >= 0 else 0,
            "request_ip": None,
            "request_user_agent": None,
            "created_at": _iso(now_dt),
            "updated_at": _iso(now_dt),
        }
        _append_request_log(row)
        return row

    t0 = time.time()

    # -------- Validate input types/enums (do NOT enforce vendor-side regex that conflicts with real stored ids) --------
    if not isinstance(api_key, str) or not api_key.strip():
        # no authenticated principal; log under any available client (if possible) as unauthorized error
        # but per rules: every invocation must create exactly one weather_requests row.
        clients = _coerce_rows(_load("api_clients.json"))
        fallback_client_id = clients[0]["id"] if clients else "unknown"
        _log_request(fallback_client_id, None, "error", 401, "unauthorized", "Missing api_key.")
        return _err("UNAUTHORIZED", "Missing api_key.")

    if not isinstance(id, str) or not id.strip():
        # Try resolve principal to log properly
        keys = _coerce_rows(_load("api_keys.json"))
        key_row = next((k for k in keys if k.get("id") == api_key or k.get("key_prefix") == api_key), None)
        client_id = key_row.get("client_id") if key_row else (_coerce_rows(_load("api_clients.json"))[0]["id"] if _coerce_rows(_load("api_clients.json")) else "unknown")
        _log_request(client_id, key_row.get("id") if key_row else None, "error", 400, "invalid_request", "Missing id to update.")
        return _err("VALIDATION_ERROR", "id must be a non-empty string.")

    if status not in ("active", "revoked"):
        keys = _coerce_rows(_load("api_keys.json"))
        key_row = next((k for k in keys if k.get("id") == api_key or k.get("key_prefix") == api_key), None)
        client_id = key_row.get("client_id") if key_row else (_coerce_rows(_load("api_clients.json"))[0]["id"] if _coerce_rows(_load("api_clients.json")) else "unknown")
        _log_request(client_id, key_row.get("id") if key_row else None, "error", 400, "invalid_request", "Invalid status; must be 'active' or 'revoked'.")
        return _err("VALIDATION_ERROR", "status must be one of: active, revoked.")

    # -------- Authenticate (explicit credential parameter) --------
    keys = _coerce_rows(_load("api_keys.json"))
    clients = _coerce_rows(_load("api_clients.json"))

    # Match by id first, then by key_prefix (client-visible value). Never compare to key_hash.
    auth_key = next((k for k in keys if k.get("id") == api_key), None)
    if auth_key is None:
        auth_key = next((k for k in keys if k.get("key_prefix") == api_key), None)

    if auth_key is None or auth_key.get("status") != "active":
        # Log (choose best-effort client_id)
        fallback_client_id = auth_key.get("client_id") if auth_key else (clients[0]["id"] if clients else "unknown")
        _log_request(fallback_client_id, auth_key.get("id") if auth_key else None, "error", 401, "unauthorized", "API key is invalid or not active.", int((time.time() - t0) * 1000))
        return _err("UNAUTHORIZED", "API key is invalid or not active.")

    client = next((c for c in clients if c.get("id") == auth_key.get("client_id")), None)
    if client is None:
        _log_request(auth_key.get("client_id"), auth_key.get("id"), "error", 401, "unauthorized", "API key client does not exist.", int((time.time() - t0) * 1000))
        return _err("UNAUTHORIZED", "API key client does not exist.")

    # Client must be active to proceed with mutation
    if client.get("status") != "active":
        http_status = 403
        st = "error"
        # If suspended, treat as rate_limited per policy hint
        if client.get("status") == "suspended":
            st = "rate_limited"
            http_status = 429
        _log_request(client.get("id"), auth_key.get("id"), st, http_status, "client_inactive", f"Client status is '{client.get('status')}', must be 'active'.", int((time.time() - t0) * 1000))
        return _err("UNAUTHORIZED", f"Client status is '{client.get('status')}', must be 'active'.")

    # -------- Enforce monthly quota for non-enterprise (observable; based on stored counter + reset_at) --------
    now = _utcnow()
    reset_at = _parse_dt(client.get("reset_at"))
    if reset_at is None:
        # malformed store; treat as validation error on server side but do not crash
        _log_request(client.get("id"), auth_key.get("id"), "error", 500, "server_error", "Client reset_at is invalid.", int((time.time() - t0) * 1000))
        return _err("CONFLICT", "Client reset_at is invalid; cannot enforce quota.")
    if now >= reset_at:
        # reset window
        client["requests_this_month"] = 0
        # set next reset_at = start of next month UTC
        y, m = now.year, now.month
        if m == 12:
            ny, nm = y + 1, 1
        else:
            ny, nm = y, m + 1
        next_reset = datetime.datetime(ny, nm, 1, tzinfo=datetime.timezone.utc)
        client["reset_at"] = _iso(next_reset)
        client["updated_at"] = _iso(now)
        _write_collection("api_clients.json", clients)

    plan = client.get("plan")
    if plan != "enterprise":
        quota = client.get("monthly_request_quota")
        used = client.get("requests_this_month")
        if not isinstance(quota, int) or quota < 0 or not isinstance(used, int) or used < 0:
            _log_request(client.get("id"), auth_key.get("id"), "error", 500, "server_error", "Client quota counters are invalid.", int((time.time() - t0) * 1000))
            return _err("CONFLICT", "Client quota counters are invalid; cannot enforce quota.")
        if used >= quota:
            _log_request(client.get("id"), auth_key.get("id"), "rate_limited", 429, "quota_exceeded", "Monthly request quota exceeded; retry after reset.", int((time.time() - t0) * 1000))
            return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded; retry after reset.", reset_at=client.get("reset_at"))

    # -------- Locate target key to update --------
    target_key = next((k for k in keys if k.get("id") == id), None)
    if target_key is None:
        _log_request(client.get("id"), auth_key.get("id"), "error", 404, "not_found", "API key id not found.", int((time.time() - t0) * 1000))
        return _err("NOT_FOUND", f"api_keys.id '{id}' was not found.")

    # Restrict updates to same client (typical vendor behavior)
    if target_key.get("client_id") != client.get("id"):
        _log_request(client.get("id"), auth_key.get("id"), "error", 403, "forbidden", "Cannot modify an API key owned by a different client.", int((time.time() - t0) * 1000))
        return _err("UNAUTHORIZED", "Cannot modify an API key owned by a different client.")

    # -------- Lifecycle transitions --------
    cur = target_key.get("status")
    allowed = {"active": ["revoked"], "revoked": []}
    if cur not in allowed:
        _log_request(client.get("id"), auth_key.get("id"), "error", 409, "invalid_transition", f"Unknown current key status '{cur}'.", int((time.time() - t0) * 1000))
        return _err("CONFLICT", f"Unknown current key status '{cur}'.")

    if status == cur:
        # Idempotent: still counts as a request; persist last_used_at? This is a management call, so don't alter last_used_at.
        _log_request(client.get("id"), auth_key.get("id"), "served", 200, None, None, int((time.time() - t0) * 1000))
        return {"api_key": target_key, "updated": False}

    if status not in allowed[cur]:
        _log_request(client.get("id"), auth_key.get("id"), "error", 409, "invalid_transition", f"Illegal transition {cur} -> {status}.", int((time.time() - t0) * 1000))
        return _err("INVALID_TRANSITION", f"Illegal status transition for api_keys: {cur} -> {status}. Only active -> revoked is permitted.")

    # -------- Apply mutation --------
    target_key["status"] = status
    target_key["updated_at"] = _iso(now)

    # Persist
    _write_collection("api_keys.json", keys)

    # Count the request against quota (non-enterprise) after successful processing as a real service would
    if plan != "enterprise":
        client["requests_this_month"] = int(client.get("requests_this_month") or 0) + 1
        client["updated_at"] = _iso(now)
        _write_collection("api_clients.json", clients)

    # Update authenticator key last_used_at on successful authenticated call
    auth_key["last_used_at"] = _iso(now)
    auth_key["updated_at"] = _iso(now)
    _write_collection("api_keys.json", keys)

    _log_request(client.get("id"), auth_key.get("id"), "served", 200, None, None, int((time.time() - t0) * 1000))
    return {"api_key": target_key, "updated": True}

def weather_requests_list(api_key, client_id=None, api_key_id=None, location_id=None, status=None, created_at_gte=None, created_at_lt=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0226000" if __import__("os").path.isdir("./environment_mix/0226000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            if s.tzinfo is None:
                return s.replace(tzinfo=datetime.timezone.utc)
            return s
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None

    def _b62(n):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
        if n <= 0:
            return "0"
        out = []
        while n:
            n, r = divmod(n, 62)
            out.append(alphabet[r])
        return "".join(reversed(out))

    def _new_id(prefix):
        ms = int(time.time() * 1000)
        jitter = int(time.time_ns() % 1000000)
        return f"{prefix}_01H{_b62(ms)}{_b62(jitter)}"

    def _find_key_row(presented):
        if not isinstance(presented, str) or not presented.strip():
            return None
        keys = _load("api_keys.json")
        for k in keys:
            if k.get("id") == presented or k.get("key_prefix") == presented:
                return k
        return None

    def _resolve_auth(presented):
        k = _find_key_row(presented)
        if not k or k.get("status") != "active":
            return None, None
        clients = _load("api_clients.json")
        c = next((cc for cc in clients if cc.get("id") == k.get("client_id")), None)
        if not c or c.get("status") != "active":
            return None, None
        return c, k

    def _log_request(reqs, client_id_, api_key_id_, status_s, http_status_code,
                     error_code=None, error_message=None, total_latency_ms=0):
        now_dt = _utcnow()
        row = {
            "id": _new_id("wthr_req"),
            "client_id": client_id_,
            "api_key_id": api_key_id_,
            "location_id": None,
            "snapshot_id": None,
            "status": status_s,
            "cache_status": None,
            "http_status_code": int(http_status_code),
            "error_code": error_code,
            "error_message": error_message,
            "upstream_latency_ms": None,
            "total_latency_ms": int(max(0, total_latency_ms)),
            "request_ip": None,
            "request_user_agent": None,
            "created_at": _iso(now_dt),
            "updated_at": _iso(now_dt),
        }
        reqs.append(row)
        _save("weather_requests.json", reqs)
        return row

    def _encode_cursor(last_row):
        payload = {"created_at": last_row.get("created_at"), "id": last_row.get("id")}
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _decode_cursor(cur):
        try:
            pad = "=" * (-len(cur) % 4)
            raw = base64.urlsafe_b64decode((cur + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict):
                return None
            if not isinstance(obj.get("created_at"), str) or not isinstance(obj.get("id"), str):
                return None
            return obj
        except Exception:
            return None

    t0 = time.time()

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("UNAUTHORIZED", "Missing API key.")
    if client_id is not None and (not isinstance(client_id, str) or not client_id.strip()):
        return _err("VALIDATION_ERROR", "client_id must be a non-empty string when provided.")
    if api_key_id is not None and (not isinstance(api_key_id, str) or not api_key_id.strip()):
        return _err("VALIDATION_ERROR", "api_key_id must be a non-empty string when provided.")
    if location_id is not None and (not isinstance(location_id, str) or not location_id.strip()):
        return _err("VALIDATION_ERROR", "location_id must be a non-empty string when provided.")
    if status is not None and status not in ("served", "error", "rate_limited"):
        return _err("VALIDATION_ERROR", "Invalid status filter.")
    if created_at_gte is not None and (not isinstance(created_at_gte, str) or _parse_dt(created_at_gte) is None):
        return _err("VALIDATION_ERROR", "created_at_gte must be an RFC3339 datetime string when provided.")
    if created_at_lt is not None and (not isinstance(created_at_lt, str) or _parse_dt(created_at_lt) is None):
        return _err("VALIDATION_ERROR", "created_at_lt must be an RFC3339 datetime string when provided.")
    if created_at_gte is not None and created_at_lt is not None:
        if _parse_dt(created_at_gte) >= _parse_dt(created_at_lt):
            return _err("VALIDATION_ERROR", "created_at_gte must be < created_at_lt.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")

    authed_client, authed_key = _resolve_auth(api_key)
    if authed_client is None:
        return _err("UNAUTHORIZED", "Invalid or inactive API key.")

    reqs = _load("weather_requests.json")

    # Filter
    rows = reqs[:]
    if client_id is not None:
        rows = [r for r in rows if r.get("client_id") == client_id]
    if api_key_id is not None:
        rows = [r for r in rows if r.get("api_key_id") == api_key_id]
    if location_id is not None:
        rows = [r for r in rows if r.get("location_id") == location_id]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if created_at_gte is not None:
        g = _parse_dt(created_at_gte)
        rows = [r for r in rows if (_parse_dt(r.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)) >= g]
    if created_at_lt is not None:
        lt = _parse_dt(created_at_lt)
        rows = [r for r in rows if (_parse_dt(r.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)) < lt]

    # Sort newest first (common audit view)
    rows.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""), reverse=True)

    # Cursor
    start_idx = 0
    if cursor is not None:
        cobj = _decode_cursor(cursor)
        if cobj is None:
            latency_ms = int((time.time() - t0) * 1000)
            _log_request(reqs, authed_client.get("id"), authed_key.get("id"), "error", 400, "invalid_request", "Invalid cursor.", latency_ms)
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        marker = (cobj["created_at"], cobj["id"])
        for i, r in enumerate(rows):
            key = (r.get("created_at") or "", r.get("id") or "")
            if key < marker:  # since reverse sorted, move past marker
                start_idx = i
                break
        else:
            start_idx = len(rows)

    page = rows[start_idx:start_idx + limit]
    has_more = (start_idx + limit) < len(rows)
    next_cursor = _encode_cursor(page[-1]) if has_more and page else None

    latency_ms = int((time.time() - t0) * 1000)
    _log_request(reqs, authed_client.get("id"), authed_key.get("id"), "served", 200, None, None, latency_ms)

    return {"data": page, "total": len(rows), "limit": limit, "has_more": has_more, "next_cursor": next_cursor}
